INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20ZPXBB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers want to test whether a new study technique improves exam scores. They recruit 80 volunteers and let each volunteer choose whether to use the new technique or their usual method. Students using the new technique score an average of 7 points higher. A critic argues the study has a flaw. Which of the following best describes the flaw?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of 80 is too small to detect a 7-point difference."},{"key":"B","text":"The study lacks a control group because all participants took the exam."},{"key":"C","text":"Self-selection into groups means differences in scores could be due to pre-existing differences between the groups rather than the technique."},{"key":"D","text":"The 7-point difference is not statistically significant because it is less than 10 points."}]$lyceon_json$::jsonb, 'C', NULL, E'When participants self-select into treatment and control groups, confounding variables undermine causal conclusions. Students who chose the new technique may already be more motivated or higher-performing, so the 7-point difference could reflect pre-existing differences rather than the technique itself. The claim about sample size is incorrect because 80 participants can be sufficient to detect a meaningful effect. The study does have a comparison group (those using their usual method), so the claim that it lacks a control group is wrong. Statistical significance depends on variability and sample size, not on an arbitrary threshold of 10 points.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21CS742', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A right circular cylinder has a volume of \\(4394\\pi\\) cubic centimeters. The height of the cylinder is twice the radius of its base. What is the height of the cylinder, in centimeters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '26', ARRAY['26'], E'Let the radius be \\(r\\) and the height be \\(h = 2r\\). The volume of a cylinder is \\(\\pi r^2 h\\), so \\(\\pi r^2(2r) = 4394\\pi\\). Dividing both sides by \\(\\pi\\) gives \\(2r^3 = 4394\\), so \\(r^3 = 2197\\). Since \\(13^3 = 2197\\), \\(r = 13\\). Therefore \\(h = 2(13) = 26\\) centimeters.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22CQYNJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set has 11 values arranged in ascending order. The mean of the data set is 47 and the median is 43. If every value in the data set is increased by 6 and then multiplied by 3, what is the new median?', NULL, $lyceon_json$[{"key":"A","text":"129"},{"key":"B","text":"141"},{"key":"C","text":"147"},{"key":"D","text":"159"}]$lyceon_json$::jsonb, 'C', NULL, E'Linear transformations apply directly to the median. Adding 6 to every value shifts the median to 43 + 6 = 49. Multiplying every value by 3 scales the median to 49 times 3 = 147. The answer 129 comes from multiplying 43 by 3 without adding 6 first. The answer 141 arises from applying the operations in reverse order: (43 times 3) + 6 = 135, then adding another 6. The answer 159 results from incorrectly using the mean (47 + 6 = 53, then 53 times 3 = 159) instead of the median.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23G3TZ6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees found that 84 drink coffee, 62 drink tea, and 23 drink both coffee and tea. If an employee is selected at random, what is the probability that the employee drinks coffee or tea?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{123}{200}\\)"},{"key":"B","text":"\\(\\dfrac{146}{200}\\)"},{"key":"C","text":"\\(\\dfrac{84}{200}\\)"},{"key":"D","text":"\\(\\dfrac{169}{200}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the inclusion-exclusion principle, P(coffee or tea) = P(coffee) + P(tea) - P(both) = 84 + 62 - 23 = 123. So the probability is 123/200. The answer 146/200 adds 84 and 62 without subtracting the 23 who drink both, double-counting those employees. The answer 84/200 considers only coffee drinkers, ignoring those who drink tea. The answer 169/200 incorrectly adds all three values (84 + 62 + 23) instead of subtracting the overlap.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23NOWSG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3(2x - 7) + 4x$?', NULL, $lyceon_json$[{"key":"A","text":"$10x - 21$"},{"key":"B","text":"$10x - 7$"},{"key":"C","text":"$6x - 21$"},{"key":"D","text":"$10x + 21$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $3 \\cdot 2x - 3 \\cdot 7 + 4x = 6x - 21 + 4x = 10x - 21$. The expression $10x - 7$ results from failing to distribute the $3$ to the constant $-7$. The expression $6x - 21$ omits the $+4x$ term entirely. The expression $10x + 21$ applies the wrong sign when multiplying $3$ by $-7$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM278W2RS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = x^2 - 9x + 14$. What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-18$"},{"key":"D","text":"$50$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 3$: $f(3) = (3)^2 - 9(3) + 14 = 9 - 27 + 14 = -4$. The value $4$ results from a sign error in the final computation. The value $-18$ comes from computing $9 - 27$ but omitting the $+14$ term. The value $50$ results from evaluating $f(-3) = 9 + 27 + 14$ instead of $f(3)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27C1VD0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a data set is given by \\(y = 2.7x + 11.4\\), where \\(x\\) is the number of weeks and \\(y\\) is the total sales in thousands. One data point is \\((9, 34.2)\\). What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"-1.5"},{"key":"B","text":"1.5"},{"key":"C","text":"-2.1"},{"key":"D","text":"2.1"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value at x = 9 is y = 2.7(9) + 11.4 = 24.3 + 11.4 = 35.7. The residual is actual minus predicted = 34.2 - 35.7 = -1.5. The answer 1.5 results from reversing the subtraction order (predicted minus actual), a sign error. The answer -2.1 results from a computational error in evaluating the line of best fit. The answer 2.1 combines both the sign reversal and the arithmetic error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27FA386', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A student''s quiz scores are 78, 83, 91, 67, and 86. What is the median of these scores?', NULL, $lyceon_json$[{"key":"A","text":"78"},{"key":"B","text":"81"},{"key":"C","text":"83"},{"key":"D","text":"86"}]$lyceon_json$::jsonb, 'C', NULL, E'Ordering the scores from least to greatest: 67, 78, 83, 86, 91. The median is the middle value, which is 83. The answer 78 reflects selecting the first value in the original list rather than sorting first. The answer 81 comes from averaging the mean and a nearby value incorrectly. The answer 86 results from picking the second-highest value instead of the true middle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27MN16Z', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $xy = 18$ and $x + y = 11$, where $x > y > 0$, what is the value of $x - y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Since $x + y = 11$ and $xy = 18$, the values $x$ and $y$ are roots of the quadratic $t^2 - 11t + 18 = 0$. The discriminant is $121 - 72 = 49$, so $t = \\frac{11 \\pm 7}{2}$, giving $t = 9$ or $t = 2$. Since $x > y$, we have $x = 9$ and $y = 2$, so $x - y = 9 - 2 = 7$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28OL4TA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 voters in a city found that 164 support a proposed park renovation. Which of the following is the best estimate of the proportion of all voters in the city who support the renovation?', NULL, $lyceon_json$[{"key":"A","text":"0.36"},{"key":"B","text":"0.41"},{"key":"C","text":"0.50"},{"key":"D","text":"0.64"}]$lyceon_json$::jsonb, 'B', NULL, E'The sample proportion is 164/400 = 0.41, which is the best estimate of the population proportion. The value 0.36 results from an arithmetic error in the division. The value 0.50 assumes an even split without using the sample data. The value 0.64 incorrectly uses (400 - 164)/400 = 236/400, giving the proportion who do not support the renovation.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29I790K', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A gym membership costs a one-time enrollment fee of 59 dollars plus a monthly fee of 27 dollars. The total cost \\(C\\), in dollars, as a function of the number of months \\(m\\) is \\(C(m) = 27m + 59\\). What is the minimum number of whole months of membership needed for the total cost to first exceed 350 dollars?', NULL, $lyceon_json$[{"key":"A","text":"10"},{"key":"B","text":"11"},{"key":"C","text":"12"},{"key":"D","text":"13"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting \\(27m + 59 > 350\\) gives \\(27m > 291\\), so \\(m > \\frac{291}{27} \\approx 10.78\\). Since \\(m\\) must be a whole number, the smallest integer greater than 10.78 is 11. Checking: \\(C(10) = 270 + 59 = 329\\), which does not exceed 350, and \\(C(11) = 297 + 59 = 356\\), which does exceed 350. The value 10 results from rounding down instead of up. The value 12 comes from an arithmetic slip in the division. The value 13 results from incorrectly setting up the inequality by omitting the enrollment fee.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AP7WWG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'In the \\(xy\\)-plane, a circle has center \\((5, -7)\\) and is tangent to the line \\(3x - 4y = 58\\). What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"\\(9\\pi\\)"},{"key":"B","text":"\\(3\\pi\\)"},{"key":"C","text":"\\(15\\pi\\)"},{"key":"D","text":"\\(225\\pi\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius equals the distance from \\((5, -7)\\) to the line \\(3x - 4y - 58 = 0\\). Using the point-to-line formula: \\(r = \\frac{|3(5) - 4(-7) - 58|}{\\sqrt{3^2 + 4^2}} = \\frac{|15 + 28 - 58|}{5} = \\frac{15}{5} = 3\\). The area is \\(\\pi r^2 = 9\\pi\\). The value \\(3\\pi\\) uses the radius as \\(\\pi r\\) instead of squaring it. The value \\(15\\pi\\) uses the numerator \\(15\\) as the radius without dividing by \\(5\\). The value \\(225\\pi\\) squares the numerator \\(15\\) to get \\(225\\) without dividing by the denominator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B5TW21', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'At how many points do the graphs of $y = x^2 + 3x - 7$ and $y = 5x - 3$ intersect?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting the expressions equal: $x^2 + 3x - 7 = 5x - 3$, which simplifies to $x^2 - 2x - 4 = 0$. The discriminant is $(-2)^2 - 4(1)(-4) = 4 + 16 = 20$. Since $20 > 0$, the quadratic has two distinct real solutions, meaning the graphs intersect at $2$ points. Choosing $0$ results from a sign error when computing the discriminant. Choosing $1$ reflects confusion with the tangency condition (discriminant equals zero). Choosing $3$ is impossible for the intersection of a parabola and a line, which can have at most $2$ intersection points.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BZGKLZ', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of the constant \\(k\\) does the system of equations \\(6x - 5y = 14\\) and \\(9x + ky = 21\\) have no solution?', NULL, $lyceon_json$[{"key":"A","text":"\\(-\\dfrac{15}{2}\\)"},{"key":"B","text":"\\(\\dfrac{15}{2}\\)"},{"key":"C","text":"\\(-\\dfrac{10}{3}\\)"},{"key":"D","text":"\\(\\dfrac{10}{3}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'A system has no solution when the lines are parallel: same slope but different intercepts. Rewriting both equations in slope-intercept form, the first gives slope \\(\\frac{6}{5}\\) and the second gives slope \\(-\\frac{9}{k}\\). Setting slopes equal: \\(\\frac{6}{5} = -\\frac{9}{k}\\), so \\(6k = -45\\) and \\(k = -\\frac{15}{2}\\). One must also verify the intercepts differ: \\(\\frac{14}{5} \\neq \\frac{21}{k}\\), which holds since \\(\\frac{21}{-15/2} = -\\frac{14}{5} \\neq \\frac{14}{5}\\). Choosing \\(\\frac{15}{2}\\) results from dropping the negative sign when cross-multiplying. The value \\(-\\frac{10}{3}\\) comes from incorrectly setting up the proportion by swapping numerators and denominators. The value \\(\\frac{10}{3}\\) combines both the sign error and the setup error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C3SSQM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 600 residents and finds that 43% favor a new transit line. The margin of error for the survey is 4 percentage points. Which of the following is a valid conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 43% of all residents favor the transit line."},{"key":"B","text":"Between 39% and 47% of all residents likely favor the transit line."},{"key":"C","text":"At most 47% of all residents favor the transit line."},{"key":"D","text":"Between 43% and 47% of all residents likely favor the transit line."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of 4 percentage points means the confidence interval is 43% minus 4% to 43% plus 4%, or 39% to 47%. The claim that exactly 43% of all residents favor it treats the sample statistic as a population parameter. The claim of at most 47% only uses the upper bound and ignores the full interval. The range 43% to 47% only adds the margin of error in one direction, omitting the lower bound of 39%.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CBNZ1S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle \\(PQR\\), the measure of angle \\(P\\) is \\(47°\\) and the measure of angle \\(Q\\) is \\(68°\\). What is the measure, in degrees, of angle \\(R\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(65°\\)"},{"key":"B","text":"\\(55°\\)"},{"key":"C","text":"\\(75°\\)"},{"key":"D","text":"\\(115°\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the interior angles of a triangle is \\(180°\\). Therefore, angle \\(R = 180° - 47° - 68° = 65°\\). The value \\(55°\\) results from an arithmetic error in the subtraction. The value \\(75°\\) comes from a different computational mistake. The value \\(115°\\) equals \\(180° - 65°\\), which is the supplement of the correct answer rather than the angle itself.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CI372R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a strong positive linear association between the number of hours studied and quiz score. Which of the following best describes this relationship?', NULL, $lyceon_json$[{"key":"A","text":"As hours studied increase, quiz scores tend to decrease."},{"key":"B","text":"As hours studied increase, quiz scores tend to increase."},{"key":"C","text":"There is no consistent relationship between hours studied and quiz scores."},{"key":"D","text":"As hours studied increase, quiz scores remain constant."}]$lyceon_json$::jsonb, 'B', NULL, E'A strong positive linear association means that as one variable increases, the other also tends to increase, so quiz scores tend to increase as hours studied increase. The description that scores tend to decrease reflects confusion between positive and negative association. Claiming no consistent relationship contradicts the strong association stated. Stating scores remain constant describes no association at all.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CKYT9I', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'The system of equations \\(3x + 7y = 47\\) and \\(3x + 2y = 22\\) has a solution \\((x, y)\\). What is the value of \\(x + y\\)?', NULL, $lyceon_json$[{"key":"A","text":"6"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"9"}]$lyceon_json$::jsonb, 'D', NULL, E'Subtracting the second equation from the first: \\((3x + 7y) - (3x + 2y) = 47 - 22\\), which gives \\(5y = 25\\) and \\(y = 5\\). Substituting into \\(3x + 2(5) = 22\\) yields \\(3x = 12\\), so \\(x = 4\\). Therefore \\(x + y = 4 + 5 = 9\\). Getting 5 alone (the value of \\(y\\)) without adding \\(x\\) reflects partial reasoning. A value of 7 comes from an arithmetic slip such as computing \\(47 - 22 = 20\\) instead of 25. A value of 8 arises from a sign error when substituting back.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CQTP74', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line \\(p\\) has the equation \\(5x + 8y = 62\\). Line \\(q\\) is perpendicular to line \\(p\\) and passes through the point \\((10, 3)\\). What is the \\(y\\)-intercept of line \\(q\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-13', ARRAY['-13'], E'Rewriting line \\(p\\) in slope-intercept form: \\(y = -\\frac{5}{8}x + \\frac{31}{4}\\), so the slope of line \\(p\\) is \\(-\\frac{5}{8}\\). The slope of a perpendicular line is the negative reciprocal: \\(\\frac{8}{5}\\). Using point-slope form with \\((10, 3)\\): \\(y - 3 = \\frac{8}{5}(x - 10)\\), which simplifies to \\(y = \\frac{8}{5}x - 16 + 3 = \\frac{8}{5}x - 13\\). The \\(y\\)-intercept is \\(-13\\).', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EQ2QYU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the age (in years) and value (in thousands of dollars) of 15 used cars. The line of best fit is \\(v = -3.1a + 29.8\\), where \\(a\\) is age and \\(v\\) is value. The correlation coefficient is \\(r = -0.93\\). Which of the following is the best interpretation of the slope in context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional year of age, the predicted value of a car decreases by 3,100 dollars."},{"key":"B","text":"For each additional year of age, the predicted value of a car decreases by 3.1 dollars."},{"key":"C","text":"A car that is 0 years old has a predicted value of 29,800 dollars."},{"key":"D","text":"Approximately 86.5% of the variation in car value is explained by age."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of -3.1 means that for each additional year of age, the predicted value decreases by 3.1 thousand dollars, or 3,100 dollars. The answer stating a decrease of 3.1 dollars ignores that the value variable is measured in thousands. The answer describing the value at age 0 interprets the y-intercept, not the slope. The answer about 86.5% of variation describes r-squared (which equals approximately 0.865), but the question asks about the slope, not the coefficient of determination.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"unit_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F50C4P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A machine fills 34 bottles in 8 minutes. At the same rate, how many minutes will it take to fill 119 bottles?', NULL, $lyceon_json$[{"key":"A","text":"24"},{"key":"B","text":"26"},{"key":"C","text":"28"},{"key":"D","text":"32"}]$lyceon_json$::jsonb, 'C', NULL, E'Set up the proportion: 34 bottles / 8 minutes = 119 bottles / x minutes. Cross-multiplying gives 34x = 952, so x = 952 / 34 = 28 minutes. The answer 24 results from an arithmetic error in the division. The answer 26 comes from incomplete simplification. The answer 32 arises from incorrectly setting up the proportion as 119/34 then rounding up and multiplying by an extra factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FAQ9P8', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If \\(\\dfrac{3(2x - 5)}{4} + 7 = \\dfrac{x}{2} + 11\\), what is the value of \\(x\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{31}{4}\\)"},{"key":"B","text":"7"},{"key":"C","text":"\\(\\dfrac{47}{4}\\)"},{"key":"D","text":"\\(\\dfrac{15}{2}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiplying both sides by 4 gives \\(3(2x - 5) + 28 = 2x + 44\\). Expanding: \\(6x - 15 + 28 = 2x + 44\\), so \\(6x + 13 = 2x + 44\\). Subtracting \\(2x\\) and 13 from both sides: \\(4x = 31\\), giving \\(x = \\frac{31}{4}\\). The value 7 comes from an arithmetic slip when combining \\(-15 + 28\\). The value \\(\\frac{47}{4}\\) results from failing to distribute the 3 to the \\(-5\\) term. The value \\(\\frac{15}{2}\\) comes from incorrectly combining like terms after clearing fractions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GGKXQE', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A delivery service charges a base fee of 19 dollars plus 3 dollars per mile for standard delivery and a flat rate of 58 dollars for express delivery. For what range of miles \\(m\\) is the standard delivery strictly cheaper than express delivery?', NULL, $lyceon_json$[{"key":"A","text":"\\(m < 13\\)"},{"key":"B","text":"\\(m \\leq 13\\)"},{"key":"C","text":"\\(m > 13\\)"},{"key":"D","text":"\\(m < 12\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Standard delivery costs \\(19 + 3m\\) dollars and express costs 58 dollars. Setting up the inequality \\(19 + 3m < 58\\) gives \\(3m < 39\\), so \\(m < 13\\). Using \\(m \\leq 13\\) incorrectly includes 13 miles, at which point both services cost exactly 58 dollars and standard is not strictly cheaper. The inequality \\(m > 13\\) reverses the direction, representing miles where standard is more expensive. The value \\(m < 12\\) results from an arithmetic error when dividing 39 by 3 or from incorrectly computing \\(58 - 19 = 36\\) instead of 39.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GYRPWR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same population. Sample A has 250 respondents and finds that 58% agree with a policy. Sample B has 1,000 respondents and finds that 54% agree. Which of the following best explains the difference in results?', NULL, $lyceon_json$[{"key":"A","text":"Sample B is more likely to be biased because it is larger."},{"key":"B","text":"The difference is most likely due to sampling variability, and Sample B's estimate is expected to have a smaller margin of error."},{"key":"C","text":"Sample A's result should be preferred because it found a higher percentage."},{"key":"D","text":"Neither result can be trusted because the two samples disagree."}]$lyceon_json$::jsonb, 'B', NULL, E'Random samples from the same population can produce different statistics due to sampling variability. Larger samples have smaller margins of error, so the 1,000-respondent estimate is expected to be more precise. The claim that a larger sample is more biased reverses the relationship between sample size and reliability. Preferring a result simply because it yielded a higher percentage has no statistical basis. Dismissing both results because they differ ignores the expected variability inherent in random sampling.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H56B3F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato yield. She randomly assigns 30 tomato plants to receive the new fertilizer and 30 plants to receive a standard fertilizer. This study is best described as which of the following?', NULL, $lyceon_json$[{"key":"A","text":"An observational study"},{"key":"B","text":"A survey"},{"key":"C","text":"An experiment"},{"key":"D","text":"A census"}]$lyceon_json$::jsonb, 'C', NULL, E'Because the researcher randomly assigns treatments (new fertilizer vs. standard fertilizer) to subjects, this is an experiment. An observational study would observe plants without assigning treatments. A survey collects self-reported data from respondents, which does not apply to measuring plant yield. A census collects data from every member of a population, whereas this study uses a sample of 60 plants.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2INEOBV', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points \\((2, 11)\\) and \\((5, 23)\\). Which of the following is the equation of this line?', NULL, $lyceon_json$[{"key":"A","text":"\\(y = 4x + 3\\)"},{"key":"B","text":"\\(y = 4x - 3\\)"},{"key":"C","text":"\\(y = 3x + 5\\)"},{"key":"D","text":"\\(y = 6x - 1\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is \\(\\frac{23 - 11}{5 - 2} = \\frac{12}{3} = 4\\). Using point-slope form with \\((2, 11)\\): \\(y - 11 = 4(x - 2)\\), which gives \\(y = 4x + 3\\). The equation \\(y = 4x - 3\\) has the correct slope but a sign error in computing the intercept. The equation \\(y = 3x + 5\\) results from an arithmetic slip when calculating the slope. The equation \\(y = 6x - 1\\) comes from an incorrect setup of the slope formula, such as adding the coordinates instead of subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JIMWT9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal forming a co-interior angle of \\(131°\\) at the first parallel line. A second transversal also crosses both parallel lines, creating a triangle between the two parallel lines and the two transversals. If the angle of this triangle at the second parallel line is \\(38°\\), what is the measure, in degrees, of the angle of the triangle at the point where the two transversals meet?', NULL, $lyceon_json$[{"key":"A","text":"\\(89°\\)"},{"key":"B","text":"\\(91°\\)"},{"key":"C","text":"\\(93°\\)"},{"key":"D","text":"\\(97°\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'The co-interior angle at the first parallel line is \\(131°\\), so the angle inside the triangle at that vertex is \\(180° - 131° = 49°\\). The triangle''s angle at the second parallel line is \\(38°\\). Since the angles of a triangle sum to \\(180°\\), the angle at the intersection of the transversals is \\(180° - 49° - 38° = 93°\\). The value \\(89°\\) results from an arithmetic slip such as computing \\(180 - 49 - 42\\). The value \\(91°\\) arises from a small subtraction error. The value \\(97°\\) comes from using \\(131°\\) directly in a subtraction rather than first finding its supplement.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JJVNA1', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function \\(f(x) = -3x + 17\\) models the number of remaining tasks in a project after \\(x\\) days. What does the value 17 represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The number of tasks completed per day"},{"key":"B","text":"The initial number of remaining tasks"},{"key":"C","text":"The number of days to complete all tasks"},{"key":"D","text":"The rate at which tasks are added each day"}]$lyceon_json$::jsonb, 'B', NULL, E'In the function \\(f(x) = -3x + 17\\), the constant 17 is the value of \\(f(0)\\), representing the initial number of remaining tasks before any days have passed. The number of tasks completed per day corresponds to the magnitude of the slope, not the constant term. The number of days to complete all tasks would require solving \\(f(x) = 0\\), which yields a different value. The rate at which tasks change is given by the slope \\(-3\\), not the constant, and the negative sign indicates tasks decrease rather than increase.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K3BJPD', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'What is the value of \\(y\\) in the solution to the system of equations below?\\n\\n\\(x + y = 17\\)\\n\\(x - y = 3\\)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Adding the two equations eliminates \\(y\\): \\((x + y) + (x - y) = 17 + 3\\), giving \\(2x = 20\\) and \\(x = 10\\). Substituting back into the first equation: \\(10 + y = 17\\), so \\(y = 7\\).', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LDSBZE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up an item by 40% over its wholesale cost and then offers a 25% employee discount on the marked-up price. If the employee pays 73.50 dollars, what was the wholesale cost of the item?', NULL, $lyceon_json$[{"key":"A","text":"52.50"},{"key":"B","text":"61.25"},{"key":"C","text":"70.00"},{"key":"D","text":"98.00"}]$lyceon_json$::jsonb, 'C', NULL, E'Let the wholesale cost be w. The marked-up price is 1.4w. After a 25% discount, the employee pays 0.75 times 1.4w = 1.05w. Setting 1.05w = 73.50 gives w = 70.00 dollars. The answer 52.50 results from incorrectly subtracting both percentages from the final price instead of working with multiplicative factors. The answer 61.25 comes from dividing 73.50 by 1.2, miscomputing the combined factor. The answer 98.00 comes from dividing 73.50 by 0.75 alone, ignoring the markup step entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LSA21K', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $f$ is defined by $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(1) = 18$ and $f(3) = 162$, what is the value of $f(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'From $f(1) = ab = 18$ and $f(3) = ab^3 = 162$, dividing the second equation by the first gives $\\frac{ab^3}{ab} = b^2 = \\frac{162}{18} = 9$, so $b = 3$ (since $b > 0$). Substituting back, $a \\cdot 3 = 18$, which gives $a = 6$. Therefore $f(0) = a \\cdot b^0 = a \\cdot 1 = 6$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N5NKVV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A cyclist travels 13 miles in 52 minutes. A runner covers 7 miles in 63 minutes. What is the positive difference, in miles per hour, between the cyclist''s speed and the runner''s speed? Round to the nearest tenth.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8.3', ARRAY['83/10', '8.3'], E'The cyclist''s speed is 13 miles / (52/60) hours = 13 / (13/15) = 15 miles per hour. The runner''s speed is 7 miles / (63/60) hours = 7 / (21/20) = 20/3 miles per hour, which is approximately 6.667 miles per hour. The positive difference is 15 - 6.667 = 8.333, which rounds to 8.3 miles per hour.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OK42CH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands at point \\(A\\) and measures the angle of elevation to the top of a building at point \\(C\\) as \\(27°\\). She walks \\(43\\) meters directly toward the building to point \\(B\\), where the angle of elevation to \\(C\\) is \\(51°\\). Which of the following expressions gives the height of the building, in meters?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{43\\sin(27°)\\sin(51°)}{\\sin(24°)}\\)"},{"key":"B","text":"\\(\\dfrac{43\\sin(27°)\\cos(51°)}{\\sin(24°)}\\)"},{"key":"C","text":"\\(\\dfrac{43\\tan(27°)\\tan(51°)}{\\tan(51°) - \\tan(27°)}\\)"},{"key":"D","text":"\\(\\dfrac{43}{\\tan(51°) - \\tan(27°)}\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'Let \\(h\\) be the building height and \\(d\\) the horizontal distance from \\(B\\) to the base. Then \\(\\tan(51°) = h/d\\) and \\(\\tan(27°) = h/(d + 43)\\). From the first equation \\(d = h/\\tan(51°)\\). Substituting into the second: \\(\\tan(27°) = h/(h/\\tan(51°) + 43)\\). Solving yields \\(h = \\frac{43\\tan(27°)\\tan(51°)}{\\tan(51°) - \\tan(27°)}\\). The expression \\(\\frac{43\\sin(27°)\\sin(51°)}{\\sin(24°)}\\) applies the sine rule to the oblique triangle formed by the sightlines but gives the slant distance to \\(C\\), not the vertical height. The expression with \\(\\cos(51°)\\) incorrectly mixes sine and cosine. The expression \\(\\frac{43}{\\tan(51°) - \\tan(27°)}\\) omits the tangent product from the numerator.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OY591Q', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cone has a height of \\(9\\) inches and a base with a diameter of \\(10\\) inches. What is the volume of the cone, in cubic inches?', NULL, $lyceon_json$[{"key":"A","text":"\\(75\\pi\\)"},{"key":"B","text":"\\(225\\pi\\)"},{"key":"C","text":"\\(300\\pi\\)"},{"key":"D","text":"\\(150\\pi\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cone is \\(V = \\frac{1}{3}\\pi r^2 h\\). The radius is half the diameter: \\(r = 5\\). So \\(V = \\frac{1}{3}\\pi(25)(9) = 75\\pi\\). The value \\(225\\pi\\) uses \\(\\pi r^2 h\\) without the \\(\\frac{1}{3}\\) factor, giving a cylinder volume. The value \\(300\\pi\\) uses the diameter \\(10\\) instead of the radius in \\(\\pi r^2 h\\). The value \\(150\\pi\\) applies the \\(\\frac{1}{3}\\) factor but uses the diameter instead of the radius, computing \\(\\frac{1}{3}\\pi(100)(9)/2\\).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P2BXQB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular garden has a length of \\(17\\) feet and a width of \\(13\\) feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '221', ARRAY['221'], E'The area of a rectangle is length times width: \\(17 \\times 13 = 221\\) square feet.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PRBTJX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The population of a town was 4,700 in 2018 and 5,358 in 2023. What is the percent increase in population from 2018 to 2023?', NULL, $lyceon_json$[{"key":"A","text":"12.3%"},{"key":"B","text":"14%"},{"key":"C","text":"15.8%"},{"key":"D","text":"87.7%"}]$lyceon_json$::jsonb, 'B', NULL, E'The increase is 5,358 - 4,700 = 658. The percent increase is (658 / 4,700) times 100 = 14%. The answer 12.3% results from a computational error in division. The answer 15.8% comes from rounding errors or miscomputing the difference. The answer 87.7% arises from dividing the original population by the increase (4,700 / 5,358) and subtracting from 100%, which is the wrong setup.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PU0OBJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at 85 dollars is on sale for 23% off. What is the sale price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"62.00"},{"key":"B","text":"65.45"},{"key":"C","text":"66.30"},{"key":"D","text":"19.55"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is 23% of 85 = 0.23 times 85 = 19.55 dollars. The sale price is 85 - 19.55 = 65.45 dollars. The answer 62.00 results from an arithmetic error when computing the percentage. The answer 66.30 comes from incorrectly using 22% instead of 23%. The answer 19.55 is the discount amount itself, not the sale price, reflecting a misread of what the question asks.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QKN75S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'The equation \\(x^2 + y^2 - 14x + 6y + 9 = 0\\) represents a circle in the \\(xy\\)-plane. What is the radius of this circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Complete the square for each variable. Rewrite as \\((x^2 - 14x) + (y^2 + 6y) = -9\\). Adding \\(49\\) and \\(9\\) to both sides: \\((x^2 - 14x + 49) + (y^2 + 6y + 9) = -9 + 49 + 9 = 49\\). This gives \\((x - 7)^2 + (y + 3)^2 = 49\\). The radius is \\(\\sqrt{49} = 7\\).', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QSDFP0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle \\(DEF\\) with the right angle at \\(F\\), \\(\\sin(D) = \\dfrac{11}{61}\\) and \\(EF = 11\\). What is the length of \\(DF\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'In right triangle \\(DEF\\) with the right angle at \\(F\\), the side opposite angle \\(D\\) is \\(EF\\) and the hypotenuse is \\(DE\\). So \\(\\sin(D) = \\frac{EF}{DE} = \\frac{11}{DE} = \\frac{11}{61}\\), giving \\(DE = 61\\). By the Pythagorean theorem, \\(DF = \\sqrt{DE^2 - EF^2} = \\sqrt{61^2 - 11^2} = \\sqrt{3721 - 121} = \\sqrt{3600} = 60\\).', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RMEPQ0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of 150 students, 57 study French, 43 study German, and 29 study both. If a student who studies French is selected at random, what is the probability that this student also studies German?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{29}{150}\\)"},{"key":"B","text":"\\(\\dfrac{29}{57}\\)"},{"key":"C","text":"\\(\\dfrac{29}{43}\\)"},{"key":"D","text":"\\(\\dfrac{57}{150}\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question: P(German | French) = P(French and German) / P(French) = 29/57. The answer 29/150 divides by the total number of students instead of conditioning on those who study French. The answer 29/43 divides by the number of German students, which reverses the condition to P(French | German). The answer 57/150 gives the unconditional probability of studying French, ignoring the German requirement entirely.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RXGHYU', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9x^4 y^3 - 6x^2 y^5}{3x^2 y^2}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^2 y - 2y^3$"},{"key":"B","text":"$3x^2 y - 2x^2 y^3$"},{"key":"C","text":"$3x^2 y - 6y^3$"},{"key":"D","text":"$3x^6 y^5 - 2x^4 y^7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing each term by $3x^2 y^2$: the first term gives $\\frac{9x^4 y^3}{3x^2 y^2} = 3x^{4-2} y^{3-2} = 3x^2 y$, and the second gives $\\frac{6x^2 y^5}{3x^2 y^2} = 2y^{5-2} = 2y^3$. The simplified result is $3x^2 y - 2y^3$. The expression $3x^2 y - 2x^2 y^3$ fails to cancel $x^2$ from the second term. The expression $3x^2 y - 6y^3$ does not divide the coefficient $6$ by $3$. The expression $3x^6 y^5 - 2x^4 y^7$ adds exponents instead of subtracting them when dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SAGK3Y', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = -3(x - 7)^2 + 41$. What is the maximum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$41$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-41$"},{"key":"D","text":"$38$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function is in vertex form $g(x) = a(x - h)^2 + k$ with $a = -3$, $h = 7$, and $k = 41$. Since $a < 0$, the parabola opens downward and the vertex $(7, 41)$ is the maximum point. The maximum value of $g(x)$ is $41$. The value $7$ confuses the $x$-coordinate of the vertex with the maximum output value. The value $-41$ applies a sign error to the correct maximum. The value $38$ likely results from an arithmetic error such as computing $41 - 3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SSZBZT', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of \\(x\\) satisfies the inequality \\(7x - 13 > 22\\)?', NULL, $lyceon_json$[{"key":"A","text":"3"},{"key":"B","text":"4"},{"key":"C","text":"5"},{"key":"D","text":"6"}]$lyceon_json$::jsonb, 'D', NULL, E'Solving \\(7x - 13 > 22\\) gives \\(7x > 35\\), so \\(x > 5\\). Among the choices, only 6 is strictly greater than 5. The value 5 fails because the inequality is strict (not \\(\\geq\\)), making it a boundary value that does not satisfy the condition. The value 4 results from an arithmetic slip in dividing 35 by 7 and rounding down. The value 3 reflects a fundamental misunderstanding of how to isolate the variable.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2STBXT7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A data set contains 8 values: 14, 19, 22, 22, 27, 31, 31, 38. If the value 38 is replaced by 54, how much does the mean increase?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'The original sum is 14 + 19 + 22 + 22 + 27 + 31 + 31 + 38 = 204. The original mean is 204 / 8 = 25.5. After replacing 38 with 54, the new sum is 204 - 38 + 54 = 220. The new mean is 220 / 8 = 27.5. The increase in the mean is 27.5 - 25.5 = 2.', NULL, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SWI8OO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for 7 cups of broth for every 3 servings of soup. How many cups of broth are needed for 9 servings?', NULL, $lyceon_json$[{"key":"A","text":"18"},{"key":"B","text":"21"},{"key":"C","text":"24"},{"key":"D","text":"27"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of broth to servings is 7:3. For 9 servings, multiply both parts by 3: (7)(3) = 21 cups. The answer 18 results from an arithmetic slip of multiplying 6 by 3. The answer 24 comes from incorrectly setting up the proportion by adding 7 and 3 then multiplying. The answer 27 comes from mistakenly multiplying 9 by 3 instead of using the correct ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T908HG', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A carpenter earns 29 dollars per hour and must pay a fixed daily equipment rental fee of 47 dollars. If the carpenter needs to earn more than 311 dollars in profit on a given day, which inequality represents all possible numbers of hours \\(h\\) the carpenter must work that day?', NULL, $lyceon_json$[{"key":"A","text":"\\(29h - 47 > 311\\)"},{"key":"B","text":"\\(29h + 47 > 311\\)"},{"key":"C","text":"\\(29h - 47 \\geq 311\\)"},{"key":"D","text":"\\(47h - 29 > 311\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The carpenter''s profit is total earnings minus the equipment fee: \\(29h - 47\\). Since the profit must be more than 311 dollars, the correct inequality is \\(29h - 47 > 311\\). Adding the fee instead of subtracting it (\\(29h + 47 > 311\\)) incorrectly treats the rental cost as additional income. Using \\(\\geq\\) instead of \\(>\\) changes the meaning from ''more than'' to ''at least,'' which does not match the strict requirement. Swapping the hourly rate and fee coefficients (\\(47h - 29\\)) misassigns which value applies per hour and which is the fixed cost.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TUK3ZA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A hospital reviews medical records and finds that patients who exercised at least 3 times per week had lower rates of heart disease than patients who exercised less frequently. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Exercising at least 3 times per week causes a reduction in heart disease."},{"key":"B","text":"There is an association between exercising at least 3 times per week and lower rates of heart disease."},{"key":"C","text":"Patients who exercise less frequently should be required to exercise more."},{"key":"D","text":"The hospital should recommend exercise only to patients with heart disease."}]$lyceon_json$::jsonb, 'B', NULL, E'Since this is an observational study (reviewing existing records without random assignment), only an association can be established, not causation. The causal claim that exercise causes a reduction in heart disease is not supported because confounding variables were not controlled through random assignment. The recommendation to require exercise goes beyond what the data supports and introduces a policy judgment. Recommending exercise only to patients with heart disease misinterprets the finding, which compares exercise frequency across all patients.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TZYW55', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 11 orange tokens, 6 purple tokens, and 8 white tokens. If one token is selected at random, what is the probability that it is purple?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{6}{25}\\)"},{"key":"B","text":"\\(\\dfrac{6}{19}\\)"},{"key":"C","text":"\\(\\dfrac{8}{25}\\)"},{"key":"D","text":"\\(\\dfrac{11}{25}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of tokens is 11 + 6 + 8 = 25. The probability of selecting a purple token is 6/25. The answer 6/19 incorrectly excludes the white tokens from the total count. The answer 8/25 gives the probability of selecting a white token rather than a purple one. The answer 11/25 gives the probability of selecting an orange token instead.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UWJ777', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'When simplified completely, the expression $\\frac{x^2 - 11x + 28}{x^2 - 3x - 4} \\cdot \\frac{x^2 + 5x + 4}{x^2 - 49}$ is equivalent to which of the following?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 1}{x + 7}$"},{"key":"B","text":"$\\frac{x + 4}{x + 7}$"},{"key":"C","text":"$\\frac{(x - 4)(x + 4)}{(x + 1)(x + 7)}$"},{"key":"D","text":"$\\frac{x - 4}{x - 7}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factoring each quadratic: $x^2 - 11x + 28 = (x - 4)(x - 7)$, $x^2 - 3x - 4 = (x - 4)(x + 1)$, $x^2 + 5x + 4 = (x + 1)(x + 4)$, and $x^2 - 49 = (x - 7)(x + 7)$. The product becomes $\\frac{(x-4)(x-7)(x+1)(x+4)}{(x-4)(x+1)(x-7)(x+7)}$. Cancelling the common factors $(x-4)$, $(x-7)$, and $(x+1)$ yields $\\frac{x+4}{x+7}$. The expression $\\frac{x+1}{x+7}$ results from cancelling the wrong numerator factor. The expression $\\frac{(x-4)(x+4)}{(x+1)(x+7)}$ reflects only partial cancellation. The expression $\\frac{x-4}{x-7}$ confuses signs in the difference-of-squares factorization.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VCE8R0', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of \\(x\\) satisfies the equation \\(7x - 19 = 30\\)?', NULL, $lyceon_json$[{"key":"A","text":"7"},{"key":"B","text":"\\(\\dfrac{11}{7}\\)"},{"key":"C","text":"49"},{"key":"D","text":"-7"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding 19 to both sides gives \\(7x = 49\\), and dividing both sides by 7 gives \\(x = 7\\). The value \\(\\frac{11}{7}\\) results from subtracting 19 from 30 to get 11 and then dividing by 7, missing the addition step. The value 49 reflects stopping at \\(7x = 49\\) and misreading that intermediate result as the answer without dividing by 7. The value \\(-7\\) results from a sign error when isolating \\(x\\).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VHO2W7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of \\(11\\) centimeters. What is the area of the circle, in square centimeters?', NULL, $lyceon_json$[{"key":"A","text":"\\(22\\pi\\)"},{"key":"B","text":"\\(121\\pi\\)"},{"key":"C","text":"\\(11\\pi\\)"},{"key":"D","text":"\\(44\\pi\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a circle is \\(\\pi r^2 = \\pi(11)^2 = 121\\pi\\) square centimeters. The value \\(22\\pi\\) equals \\(2\\pi(11)\\), the circumference rather than the area. The value \\(11\\pi\\) uses \\(\\pi r\\) instead of \\(\\pi r^2\\), omitting the squaring. The value \\(44\\pi\\) equals \\(4\\pi(11)\\), doubling the circumference formula.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W0HXTL', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the \\(y\\)-intercept of the line \\(9x - 4y = 36\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\((0, 9)\\)"},{"key":"B","text":"\\((0, -9)\\)"},{"key":"C","text":"\\((0, 4)\\)"},{"key":"D","text":"\\((0, -4)\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting \\(x = 0\\) in \\(9x - 4y = 36\\) gives \\(-4y = 36\\), so \\(y = -9\\). The \\(y\\)-intercept is \\((0, -9)\\). The point \\((0, 9)\\) results from dropping the negative sign when dividing by \\(-4\\). The point \\((0, 4)\\) comes from dividing 36 by 9 instead of by \\(-4\\), confusing the coefficient of \\(x\\) with that of \\(y\\). The point \\((0, -4)\\) results from using the coefficient of \\(y\\) as the intercept value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WE37PU', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is one solution to the equation $x^2 - 13x + 42 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$13$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring gives $x^2 - 13x + 42 = (x - 6)(x - 7) = 0$, so $x = 6$ or $x = 7$. The value $6$ is one solution. The value $-6$ applies the wrong sign to a root; the factors are $(x - 6)$, not $(x + 6)$. The value $13$ confuses the sum of the roots with a solution itself. The value $-7$ applies the wrong sign to the other root.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XWSWCZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle \\(ABC\\), side \\(BC\\) is extended to point \\(D\\) so that the exterior angle \\(ACD = 137°\\). The bisector of angle \\(BAC\\) meets \\(\\overline{BC}\\) at point \\(E\\), and angle \\(AEC = 109°\\). What is the measure, in degrees, of angle \\(ABC\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(71°\\)"},{"key":"B","text":"\\(81°\\)"},{"key":"C","text":"\\(84°\\)"},{"key":"D","text":"\\(99°\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'The exterior angle \\(ACD = 137°\\) means the interior angle \\(ACB = 180° - 137° = 43°\\). In triangle \\(AEC\\), the angles sum to \\(180°\\): angle \\(EAC = 180° - 109° - 43° = 28°\\). Since \\(AE\\) bisects angle \\(BAC\\), the full angle \\(BAC = 2(28°) = 56°\\). In triangle \\(ABC\\), angle \\(ABC = 180° - 56° - 43° = 81°\\). The value \\(71°\\) equals \\(180° - 109°\\), which confuses the supplementary angle of \\(AEC\\) with the answer. The value \\(84°\\) results from an arithmetic error in the subtraction. The value \\(99°\\) comes from incorrectly applying the exterior angle theorem as \\(137° - 38°\\).', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y70098', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one of the acute angles measures \\(34°\\). What is the measure, in degrees, of the other acute angle?', NULL, $lyceon_json$[{"key":"A","text":"\\(146°\\)"},{"key":"B","text":"\\(56°\\)"},{"key":"C","text":"\\(34°\\)"},{"key":"D","text":"\\(66°\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'In a right triangle the two acute angles are complementary, summing to \\(90°\\). The other acute angle is \\(90° - 34° = 56°\\). The value \\(146°\\) results from subtracting from \\(180°\\) instead of \\(90°\\), confusing supplementary with complementary. The value \\(34°\\) assumes both acute angles are equal, which is not given. The value \\(66°\\) arises from an arithmetic error in the subtraction.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z34GAR', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'A plumber charges a flat fee of 47 dollars plus 31 dollars per hour. A second plumber charges a flat fee of 23 dollars plus 37 dollars per hour. After how many hours will both plumbers charge the same total amount?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Setting the two cost expressions equal: \\(47 + 31h = 23 + 37h\\). Subtracting \\(31h\\) from both sides: \\(47 = 23 + 6h\\). Subtracting 23: \\(24 = 6h\\). Dividing by 6: \\(h = 4\\). Both plumbers charge the same amount after 4 hours.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZXTQ48', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function \\(g\\) is defined such that \\(g(1) = 23\\) and \\(g(9) = -17\\). For what value of \\(x\\) does \\(g(x) = 0\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{33}{5}\\)"},{"key":"B","text":"\\(\\dfrac{28}{5}\\)"},{"key":"C","text":"\\(\\dfrac{23}{5}\\)"},{"key":"D","text":"\\(\\dfrac{18}{5}\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope of \\(g\\) is \\(\\frac{-17 - 23}{9 - 1} = \\frac{-40}{8} = -5\\). Using point-slope form with \\((1, 23)\\): \\(g(x) = -5(x - 1) + 23 = -5x + 5 + 23 = -5x + 28\\). Setting \\(g(x) = 0\\): \\(-5x + 28 = 0\\), so \\(x = \\frac{28}{5}\\). The value \\(\\frac{33}{5}\\) results from a sign error when computing the constant term. The value \\(\\frac{23}{5}\\) comes from using only the \\(y\\)-value at \\(x = 1\\) without adjusting for the slope offset. The value \\(\\frac{18}{5}\\) results from an arithmetic slip when adding 5 and 23.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW203HDPI', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support Sengupta''s claim?', E'Ornithologist Priya Sengupta has argued that urban starling populations in temperate cities have developed shorter migration distances over the past fifty years compared to their rural counterparts. She attributes this shift to the urban heat island effect, which provides warmer winter temperatures and more reliable food sources in cities, reducing the survival advantage of long-distance migration.', $lyceon_json$[{"key":"A","text":"Urban starlings in cities with pronounced heat islands overwinter an average of 370 kilometers closer to their breeding sites than rural starlings in the same latitude band."},{"key":"B","text":"Rural starling populations have remained genetically identical to urban populations despite fifty years of geographic separation during winter months."},{"key":"C","text":"Starling populations in tropical cities, which lack a significant heat island differential, migrate the same distances as nearby rural populations."},{"key":"D","text":"Urban starlings consume a wider variety of food types during summer months than rural starlings do."}]$lyceon_json$::jsonb, 'A', NULL, E'Sengupta claims urban starlings migrate shorter distances because of urban heat islands. A finding that urban starlings in heat-island cities overwinter significantly closer to breeding sites than rural counterparts at the same latitude directly confirms the predicted outcome. The finding about genetic identity addresses population genetics rather than migration distance. While the finding about tropical cities lacking a heat island differential is tangentially related, it addresses a different climate context and does not directly measure migration shortening in temperate cities. The finding about summer food variety concerns a different season and does not address migration distance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20LS1PE', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary about sleep patterns in migratory birds and wants to present the finding that certain species can sleep with one eye open while flying. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2120CCQ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the documentary filmmaker arrived at the remote village in northern Bhutan, she discovered that the elders ______ an oral history tradition spanning at least eleven generations, though no written records existed to corroborate their accounts.', $lyceon_json$[{"key":"A","text":"maintains"},{"key":"B","text":"maintaining"},{"key":"C","text":"have maintained"},{"key":"D","text":"had maintained"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence describes a situation in the past: the filmmaker ''arrived'' and ''discovered.'' The elders'' maintenance of the oral history tradition began before the filmmaker''s arrival and continued up to that point, which calls for the past perfect tense. ''Had maintained'' correctly signals an action that was already in progress before another past event. The singular ''maintains'' does not agree with the plural subject ''elders.'' The participle ''maintaining'' lacks a helping verb and cannot serve as the main verb of the clause. The present perfect ''have maintained'' is inconsistent with the past-tense narrative context established by ''arrived'' and ''discovered.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 65, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21EK9PC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Historian Marisol Vega argues that the collapse of the Wari Empire in the 11th century was not sudden but rather a protracted decline driven by ecological pressures. Some archaeologists, however, contend that Vega''s timeline is __________, pointing to ceramic evidence suggesting the empire''s peripheral settlements were abandoned over the span of merely two decades.', $lyceon_json$[{"key":"A","text":"vindicated"},{"key":"B","text":"overstated"},{"key":"C","text":"prescient"},{"key":"D","text":"endorsed"}]$lyceon_json$::jsonb, 'B', NULL, E'The archaeologists challenge Vega''s claim that the decline was "protracted" by presenting evidence of rapid abandonment within just two decades, suggesting Vega has exaggerated the length of the decline. "Overstated" means represented as greater than is actually the case, which aligns with the critics'' argument that the timeline was not as drawn-out as Vega claims. "Vindicated" means proven to be right, which contradicts the archaeologists'' critical stance. "Prescient" means having foresight about the future, which is irrelevant to a dispute about the duration of a historical decline. "Endorsed" means supported or approved, which is the opposite of the challenging position the archaeologists are taking.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21HDF29', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the overall structure of the text?', E'Ecologist Raina Plowright has documented how land-use changes push bat populations into closer contact with livestock and humans, increasing the probability of viral spillover events. Her work does not, however, frame bats as inherently dangerous vectors. Instead, Plowright emphasizes that spillover is a consequence of habitat disruption: when forests are fragmented, stressed bat colonies shed more virus, and the remaining landscape funnels both bats and people into the same diminished spaces.', $lyceon_json$[{"key":"A","text":"It anticipates a potential misinterpretation of Plowright's research and sets up the clarification that follows."},{"key":"B","text":"It introduces a finding that contradicts the claim made in the first sentence about viral spillover."},{"key":"C","text":"It provides statistical evidence supporting the connection between habitat loss and disease transmission."},{"key":"D","text":"It shifts the focus from Plowright's research to a broader debate among ecologists about bat conservation."}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence ("Her work does not, however, frame bats as inherently dangerous vectors") preemptively addresses a likely misreading: that documenting bat-to-human viral spillover means portraying bats as inherently dangerous. The word "however" signals a pivot, and the third sentence beginning with "Instead" delivers the intended framing. This structure shows the second sentence anticipating a misinterpretation and setting up the corrective clarification. The second sentence does not contradict the first; it qualifies how Plowright''s findings should be understood, not what she found. No statistical evidence appears anywhere in the passage, so attributing statistical support to the second sentence is unsupported. The passage discusses only Plowright''s perspective and never mentions other ecologists or a broader conservation debate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21KULOZ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Turku in Finland have found that the Arctic fox (Vulpes lagopus) adjusts its hunting strategy based on snow depth. In regions where snow cover exceeds 40 centimeters, the foxes rely almost exclusively on auditory cues to locate rodents beneath the surface, tilting their heads to pinpoint sounds before pouncing. In contrast, foxes in areas with shallower snow cover employ a more varied approach, combining visual tracking with scent detection. The study, published in 2023, analyzed 1,700 hunting attempts across eleven fox populations and determined that snow depth was the single strongest predictor of hunting method, outweighing factors such as prey density and ambient temperature.', $lyceon_json$[{"key":"A","text":"Arctic foxes modify their hunting techniques primarily in response to snow depth rather than other environmental variables."},{"key":"B","text":"Arctic foxes in Finland have developed unique adaptations that distinguish them from fox populations in other Arctic regions."},{"key":"C","text":"Auditory hunting is the most energy-efficient method available to Arctic foxes regardless of environmental conditions."},{"key":"D","text":"Researchers at the University of Turku pioneered a new methodology for studying predator behavior in extreme climates."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Arctic foxes change hunting strategies based on snow depth and states that snow depth was the strongest predictor of hunting method. The correct choice captures this central finding. The claim that Finnish foxes differ from other Arctic populations introduces a comparison the passage never makes. The assertion that auditory hunting is most energy-efficient regardless of conditions overstates what the passage says, since auditory hunting is linked specifically to deep snow. The claim about pioneering a new methodology focuses on the researchers rather than the study''s findings about fox behavior.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21X92JB', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, which choice most logically follows from El-Azar''s findings?', E'Economist Fatima El-Azar has studied the pricing behavior of independent bookstores in seven mid-sized European cities. She found that stores located within 200 meters of a university campus charged, on average, 11 percent less for identical titles than stores in the same city located more than two kilometers from a campus. However, the campus-adjacent stores reported higher overall revenue per square meter. El-Azar noted that these stores also stocked a narrower selection of titles, concentrating on high-turnover academic and literary fiction categories while largely forgoing specialty genres such as regional history and rare editions.', $lyceon_json$[{"key":"A","text":"Campus-adjacent bookstores compensate for lower per-unit prices by achieving higher sales volume through a focused inventory strategy."},{"key":"B","text":"Independent bookstores near universities are less profitable than those located farther from campuses because of their lower prices."},{"key":"C","text":"Bookstores that stock specialty genres such as regional history consistently generate more revenue per square meter than those focusing on academic titles."},{"key":"D","text":"The pricing differences El-Azar observed are primarily caused by differences in municipal tax rates between campus-adjacent and non-campus commercial zones."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that campus-adjacent stores charge less per title yet earn higher revenue per square meter, and they stock a narrower range of high-turnover categories. The logical inference is that focused inventory drives higher sales volume, offsetting lower prices. The claim that campus-adjacent stores are less profitable contradicts the passage''s finding of higher revenue per square meter. The suggestion that specialty-genre stores generate more revenue contradicts the data showing campus-adjacent stores with narrower selections outperform on revenue per square meter. The attribution to municipal tax rates introduces an external factor the passage never mentions or implies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23E2DE2', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the early twentieth century, the Mexican muralist movement sought to make art accessible to ordinary citizens by painting large-scale works on public buildings. The muralists drew on indigenous cultural traditions and revolutionary politics to craft their imagery. __________ their counterparts in the European avant-garde during the same period generally rejected public engagement in favor of formal experimentation intended for gallery audiences.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"In addition,"},{"key":"C","text":"By contrast,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes the Mexican muralists making art accessible to ordinary citizens through public buildings, then describes European avant-garde artists rejecting public engagement in favor of gallery audiences. These are opposing approaches, so "By contrast," correctly signals the shift from one stance to its opposite. "Similarly," falsely implies the two groups shared the same approach, when they took opposite positions on public engagement. "In addition," suggests the second idea supplements the first rather than opposing it. "Consequently," incorrectly implies the European artists'' approach was caused by the Mexican muralists'' choices, when the passage draws a parallel comparison, not a causal chain.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
