INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29AS59F', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an essay for an architecture class and wants to challenge the common assumption that brutalist buildings are inherently unwelcoming by presenting evidence of community attachment. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B6KJ8V', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly support Adeyemi''s argument about Equiano''s rhetorical strategy?', E'Literary scholar Marcus Adeyemi has argued that the 19th-century Nigerian author Olaudah Equiano strategically varied his narrative voice throughout "The Interesting Narrative" not merely for stylistic effect but to address distinct audience segments within a single text. Adeyemi contends that passages written in a formal, Latinate register were calibrated for parliamentary abolitionists who valued classical erudition, while passages employing colloquial English and vivid sensory detail targeted a broader reading public whose sympathy depended on emotional immediacy rather than intellectual authority.', $lyceon_json$[{"key":"A","text":"Equiano's personal correspondence reveals that he consciously revised certain chapters to use more formal diction after learning that members of Parliament would receive copies, while leaving other chapters in their original colloquial style for the general edition."},{"key":"B","text":"Other 18th-century autobiographies by formerly enslaved writers also alternate between formal and colloquial registers, suggesting this was a common convention of the genre."},{"key":"C","text":"Equiano's publisher marketed the book exclusively to parliamentary abolitionists and did not pursue broader public distribution until after the first edition sold out."},{"key":"D","text":"Linguistic analysis shows that Equiano's formal passages contain a higher density of subordinate clauses than his colloquial passages, confirming a measurable difference in register."}]$lyceon_json$::jsonb, 'A', NULL, E'Adeyemi''s specific claim is that Equiano intentionally varied register to target different audiences. Correspondence showing Equiano deliberately revised chapters for a parliamentary audience while preserving colloquial style for the general edition directly evidences intentional audience-calibrated variation. The finding that other writers also alternated registers suggests a genre convention, which would actually undermine the claim that Equiano''s variation was a deliberate targeting strategy rather than a standard practice. The claim about exclusive marketing to parliamentarians contradicts the premise that Equiano addressed distinct audience segments within a single text. The linguistic analysis confirming measurable register differences only establishes that the variation exists, not that it was strategically motivated by audience considerations, making it insufficient to support the intentionality claim.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BAI0ET', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the text, what can most reasonably be inferred about the relationship between language and mathematical processing?', E'Neuroscientist Emeka Obi has investigated how bilingual individuals process numerical information. In a series of timed experiments, Obi found that participants who learned basic arithmetic in their first language (L1) performed addition and multiplication problems 23 percent faster when the problems were presented in L1 than in their second language (L2). However, when the same participants solved novel algebraic equations they had never encountered in either language, the speed difference between L1 and L2 presentation dropped to a statistically insignificant 2 percent. Obi noted that the participants reported experiencing arithmetic in L1 as "automatic" but described working through algebra problems as requiring deliberate, language-independent reasoning regardless of the presentation language.', $lyceon_json$[{"key":"A","text":"Familiar arithmetic operations are encoded in a language-specific manner, while unfamiliar mathematical reasoning relies on cognitive processes that are largely independent of language."},{"key":"B","text":"Bilingual individuals are inherently better at algebra than monolingual individuals because they can draw on two linguistic frameworks for problem-solving."},{"key":"C","text":"Mathematical ability in a second language always improves to match first-language proficiency after sufficient exposure to algebraic concepts."},{"key":"D","text":"The speed advantage in first-language arithmetic results from differences in the visual processing of numerals rather than from linguistic encoding of operations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows a large L1 speed advantage for familiar arithmetic but a negligible difference for novel algebra, and participants described arithmetic as automatic but algebra as deliberate and language-independent. The correct inference is that familiar arithmetic is stored in language-specific form while novel reasoning operates independently of language. The claim about bilingual superiority over monolingual individuals in algebra introduces a comparison the study never examined. The assertion that second-language math always improves to match first-language proficiency makes a universal claim unsupported by the study''s findings about novel versus familiar tasks. The attribution of the speed advantage to visual numeral processing contradicts participants'' reports of arithmetic feeling linguistically automatic, and the passage does not mention visual processing differences.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BUPGJ7', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Each of the nineteen ceramic fragments unearthed during the excavation of a Mississippian-era settlement near Cahokia ______ trace mineral compositions suggesting that the clay was sourced from riverbeds more than two hundred kilometers from the site.', $lyceon_json$[{"key":"A","text":"display"},{"key":"B","text":"displays"},{"key":"C","text":"have displayed"},{"key":"D","text":"displaying"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is ''Each,'' which is always singular regardless of the prepositional phrase that follows it. Although ''nineteen ceramic fragments'' is plural, it is the object of the preposition ''of'' and does not govern the verb. The singular ''displays'' correctly agrees with ''Each.'' The plural forms ''display'' and ''have displayed'' incorrectly match the verb to ''fragments'' rather than to ''Each.'' The participle ''displaying'' lacks a helping verb and cannot serve as the sentence''s main verb, leaving the sentence without a complete predicate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BVAV0V', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The Guiana Highlands of South America harbor thousands of plant species found nowhere else on Earth. Many of these species evolved in isolation atop flat-topped mountains known as tepuis. __________ botanists have long traveled to the region to catalog its extraordinary biodiversity.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that the Guiana Highlands contain thousands of unique plant species, and the sentence after the blank states that botanists have traveled there to catalog biodiversity. The second idea follows logically from the first as a result, so "Accordingly," correctly signals that cause-and-effect relationship. "Nevertheless," incorrectly introduces a concession, implying the botanists'' visits happened despite something surprising. "In contrast," wrongly signals an opposition between the two ideas, when no opposing claim is present. "Meanwhile," implies simultaneous but unrelated events, which misrepresents the logical connection between the unique biodiversity and the motivation for botanical expeditions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CSSNWI', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts housed in the university''s east wing ______ several illuminated texts dating to the fourteenth century.', $lyceon_json$[{"key":"A","text":"includes"},{"key":"B","text":"include"},{"key":"C","text":"are including"},{"key":"D","text":"have included"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is ''collection,'' which is singular, so the verb must also be singular. The prepositional phrase ''of rare manuscripts housed in the university''s east wing'' modifies ''collection'' but does not change the number of the subject. The singular present-tense form ''includes'' correctly agrees with ''collection.'' The plural forms ''include,'' ''are including,'' and ''have included'' all fail to agree with the singular subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DPW2BF', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken Ishida''s hypothesis?', E'Geochemist Tomoko Ishida has proposed that the high concentration of rare earth elements found in certain deep-ocean clay deposits originates not from hydrothermal vents, as previously assumed, but from the slow dissolution of cosmic micrometeorites that accumulate on the seafloor over millions of years. She contends that the isotopic ratios of neodymium and cerium in these clays more closely match extraterrestrial samples than they match known hydrothermal signatures.', $lyceon_json$[{"key":"A","text":"Analysis of the neodymium and cerium isotopic ratios in the deep-ocean clays shows they fall within the range typical of hydrothermal vent emissions and diverge significantly from meteoritic samples."},{"key":"B","text":"Cosmic micrometeorites accumulate on the seafloor at a rate of approximately 30,000 metric tons per year globally."},{"key":"C","text":"Some rare earth elements found in deep-ocean clays have industrial applications in electronics manufacturing."},{"key":"D","text":"Hydrothermal vents are also known to release trace amounts of platinum and iridium into surrounding sediments."}]$lyceon_json$::jsonb, 'A', NULL, E'Ishida''s hypothesis rests on the claim that isotopic ratios in the clays match extraterrestrial sources rather than hydrothermal signatures. A finding that the ratios actually match hydrothermal emissions and diverge from meteoritic samples directly contradicts her key evidence. The accumulation rate of micrometeorites does not address whether they are the source of the rare earth elements in these particular clays. The industrial applications of rare earth elements are irrelevant to the question of their geological origin. The release of platinum and iridium from hydrothermal vents concerns different elements and does not address the isotopic ratios central to Ishida''s argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E84860', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Kaito Fujimura spent three summers cataloging beetle species in the cloud forests of Veracruz. His team identified forty-seven species not previously recorded in the ______ the findings prompted Mexico''s environmental ministry to designate the area as a protected biological corridor.', $lyceon_json$[{"key":"A","text":"region, the"},{"key":"B","text":"region the"},{"key":"C","text":"region. The"},{"key":"D","text":"region, or the"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank (''His team identified forty-seven species not previously recorded in the region'') and the sentence after (''the findings prompted Mexico''s environmental ministry to designate the area as a protected biological corridor'') are both independent clauses. A period correctly separates two independent clauses. Using only a comma between them creates a comma splice. Omitting all punctuation produces a fused sentence. Inserting ''or'' with a comma introduces a false alternative relationship that distorts the meaning of the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HAYYC5', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, the physician Ignaz Semmelweis observed that the mortality rate in the maternity ward staffed by doctors was nearly five times higher than in the ward staffed by midwives. He hypothesized that doctors were transferring "cadaverous particles" from autopsies to patients and instituted a mandatory handwashing protocol with chlorinated lime solution. Mortality rates fell dramatically. Yet Semmelweis''s colleagues rejected his findings, partly because germ theory had not yet been established and partly because his hypothesis implicitly blamed physicians for their patients'' deaths.', $lyceon_json$[{"key":"A","text":"It presents a medical observation, describes the response it prompted, and then explains why that response was not widely accepted."},{"key":"B","text":"It compares two competing medical theories and evaluates which one was ultimately proven correct."},{"key":"C","text":"It chronicles the major discoveries that led to the establishment of germ theory in the 19th century."},{"key":"D","text":"It criticizes the medical community for ignoring evidence that could have saved lives."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage follows a three-part structure: first, Semmelweis observes a disparity in mortality rates (the medical observation); second, he hypothesizes a cause and institutes handwashing (the response); third, his colleagues reject the findings for stated reasons (why the response was not accepted). The text does not present two competing theories or evaluate which was correct; it describes only Semmelweis''s hypothesis and notes that germ theory did not yet exist. Rather than chronicling the development of germ theory, the passage focuses narrowly on one episode that predated germ theory''s acceptance. While the passage notes the rejection of Semmelweis''s findings, it explains the reasons for that rejection in neutral, descriptive terms rather than adopting a critical or condemnatory tone toward the medical community.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 65, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HPOIWG', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Voyager 1 spacecraft, which was launched in 1977 and has since traveled farther from Earth than any other human-made ______ continues to transmit scientific data back to NASA''s Deep Space Network despite operating on less power than a standard household light bulb.', $lyceon_json$[{"key":"A","text":"object continues"},{"key":"B","text":"object. It continues"},{"key":"C","text":"object— continues"},{"key":"D","text":"object, continues"}]$lyceon_json$::jsonb, 'D', NULL, E'The main clause of the sentence is ''The Voyager 1 spacecraft...continues to transmit scientific data.'' The nonrestrictive relative clause ''which was launched in 1977 and has since traveled farther from Earth than any other human-made object'' is set off by commas. Since a comma already opens this relative clause after ''spacecraft,'' a matching comma must close it after ''object'' before the main verb ''continues.'' Omitting the comma fails to properly close the nonrestrictive clause. Using a period after ''object'' would leave ''The Voyager 1 spacecraft'' as a fragment with no main verb. An em dash after ''object'' creates mismatched delimiters, since the clause was opened with a comma, not a dash.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IZJJT1', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the text as a whole?', E'The fruit fly Drosophila melanogaster has been a mainstay of genetics research since Thomas Hunt Morgan''s experiments in 1910. Its short generation time of roughly ten days, the ease of maintaining large colonies in small laboratory spaces, and the availability of its fully sequenced genome make it an unusually practical model organism for studying hereditary mechanisms.', $lyceon_json$[{"key":"A","text":"It explains why a particular organism is well suited for a specific type of scientific research."},{"key":"B","text":"It argues that fruit fly research has produced more significant discoveries than research using other organisms."},{"key":"C","text":"It traces the historical development of genetics from early experiments to modern genomic sequencing."},{"key":"D","text":"It describes a controversy among geneticists about the best model organism for laboratory studies."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage identifies the fruit fly as a mainstay of genetics research and then lists three specific attributes (short generation time, easy maintenance, fully sequenced genome) that make it practical for studying hereditary mechanisms. This structure directly supports the idea that the text explains why a particular organism is well suited for genetic research. The claim that fruit fly research has produced more significant discoveries than other organisms'' research goes beyond anything stated in the passage, which never compares discovery outcomes. While the passage mentions Morgan''s 1910 experiments and genomic sequencing, it does not trace an historical arc of genetics as a discipline; these details serve only to contextualize the fruit fly''s research utility. The passage presents no disagreement among scientists, so describing a controversy is unsupported.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JIKIYA', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'The playwright Adrienne Kenworthy deliberately structures her dialogue so that characters'' exchanges feel jagged and incomplete, mirroring the fragmented way people actually converse. Critics who describe her writing as "polished" mischaracterize its essential quality: Kenworthy''s genius lies precisely in how __________ her prose appears, even though every halting phrase is carefully orchestrated.', $lyceon_json$[{"key":"A","text":"artless"},{"key":"B","text":"coherent"},{"key":"C","text":"prolific"},{"key":"D","text":"esoteric"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage sets up a paradox: Kenworthy''s writing is carefully orchestrated but designed to seem unpolished, jagged, and incomplete. The blank requires a word meaning "lacking in art or skill" as an appearance, which contrasts with the deliberate craftsmanship underneath. "Artless" means appearing natural and without artifice, capturing the paradox that the prose looks unrefined despite being meticulously crafted. "Coherent" means logically connected and consistent, which contradicts the description of dialogue as jagged and fragmented. "Prolific" means producing great quantities of work, which relates to output volume rather than the quality or style of the prose. "Esoteric" means understood by only a small group with specialized knowledge, which addresses accessibility rather than the studied roughness the passage describes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JJDVE8', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'The restoration of the 14th-century fresco required the conservator to adopt a remarkably __________ approach, applying each pigment with exacting care to avoid damaging the fragile plaster underneath.', $lyceon_json$[{"key":"A","text":"meticulous"},{"key":"B","text":"impulsive"},{"key":"C","text":"dismissive"},{"key":"D","text":"combative"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a conservator applying pigments with "exacting care" to avoid damage, which directly signals a painstaking, detail-oriented method. "Meticulous" means showing great attention to detail, fitting perfectly. "Impulsive" means acting without forethought, contradicting the careful approach described. "Dismissive" means showing a lack of interest or respect, which is irrelevant to the careful restoration process. "Combative" means ready to fight or argue, which has no connection to the delicate work described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JXWDSE', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would Schluessel (Text 2) most likely respond to Yopak''s proposal in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K147M5', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the senator''s proposed amendment to the agricultural subsidy bill nor the alternative framework drafted by the bipartisan ______ the concerns raised by small-farm advocacy groups during the committee hearings held in March.', $lyceon_json$[{"key":"A","text":"coalition have addressed"},{"key":"B","text":"coalition were addressing"},{"key":"C","text":"coalition has addressed"},{"key":"D","text":"coalition addressing"}]$lyceon_json$::jsonb, 'C', NULL, E'In a ''neither...nor'' construction, the verb agrees with the subject closer to it—in this case, ''framework,'' which is singular. The singular ''has addressed'' correctly agrees with ''framework.'' The plural forms ''have addressed'' and ''were addressing'' incorrectly treat the subject as plural. The participle ''addressing'' without a helping verb cannot function as a finite verb, leaving the sentence without a main predicate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LM1793', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'The ceramic artist Luisa Mendoza has spent two decades developing a firing technique she calls "thermal layering," in which a single vessel undergoes seven separate kiln cycles at progressively lower temperatures. Each cycle deposits a microscopically thin glaze stratum, and the cumulative effect produces an iridescent surface that shifts color depending on the angle of observation. Art critics have praised the visual results, but Mendoza insists that her primary motivation is structural: the layered glazes create a composite shell that makes her pieces roughly three times more resistant to fracture than conventionally fired stoneware of the same thickness. She views the iridescence as a fortunate byproduct rather than the goal of her process.', $lyceon_json$[{"key":"A","text":"Mendoza's thermal layering technique is valued by critics for its visual effects, but Mendoza herself regards increased structural durability as its principal purpose."},{"key":"B","text":"Mendoza developed thermal layering because she wanted to create iridescent surfaces that would distinguish her work from other ceramic artists' pieces."},{"key":"C","text":"Art critics have consistently favored Mendoza's ceramics over conventionally fired stoneware because of their superior fracture resistance."},{"key":"D","text":"Thermal layering requires seven kiln cycles, making it a significantly more time-consuming process than any other ceramic technique currently in use."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the contrast between why critics value Mendoza''s work (visual iridescence) and why Mendoza herself developed thermal layering (structural durability). The correct choice captures both sides of this contrast. The claim that Mendoza developed the technique to create iridescent surfaces directly contradicts the passage, which says she views iridescence as a byproduct. The suggestion that critics favor Mendoza''s work for fracture resistance misattributes their praise, since the passage states critics praise the visual results. The assertion that thermal layering is more time-consuming than any other ceramic technique extends beyond what the passage states, which describes only the process without comparing its duration to all other methods.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N660BX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geochemist Farida El-Shazly and her team analyzed strontium isotope ratios in 4,200-year-old skeletal remains from the Nile Delta to determine whether the individuals were local or had migrated from elsewhere. The ratios in most of the remains matched those found in local bedrock and water sources. __________ a subset of seventeen skeletons exhibited strontium signatures consistent with geological formations in the Eastern Desert, roughly 300 kilometers away, suggesting that at least some members of the community had roots outside the Delta.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"In other words,"},{"key":"C","text":"However,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank establishes that most skeletal remains matched local geological signatures, while the sentence after the blank introduces a subset of seventeen skeletons with non-local signatures. This is a genuine exception to the general finding, so "However," correctly signals the contrast between the majority pattern and the minority anomaly. "Furthermore," would incorrectly frame the non-local subset as an additional supporting point rather than a departure from the local-match pattern. "In other words," falsely implies the subsequent sentence restates the same idea, when it actually introduces contradictory evidence. "For instance," wrongly suggests the seventeen skeletons are an example of the local-match finding, when they are in fact the opposite case.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
