INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O39UTZ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Paleoclimatologist Sven Lindqvist analyzed oxygen isotope ratios in stalagmites from a cave system in northern Laos. His data pointed to a striking ______ monsoon intensity in the region had fluctuated far more dramatically during the thirteenth century than any existing climate model predicted.', $lyceon_json$[{"key":"A","text":"conclusion: monsoon"},{"key":"B","text":"conclusion, monsoon"},{"key":"C","text":"conclusion monsoon"},{"key":"D","text":"conclusion, yet monsoon"}]$lyceon_json$::jsonb, 'A', NULL, E'A colon is the correct choice here because the second independent clause directly explains what the ''striking conclusion'' was: that monsoon intensity fluctuated more dramatically than models predicted. The colon signals that what follows elaborates on or specifies what precedes it. A comma alone creates a comma splice between two independent clauses. Omitting punctuation entirely produces a fused sentence. Using ''yet'' introduces a contrast that is logically incoherent, since the second clause is not contradicting the first but rather restating the conclusion''s content.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OUESB8', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'In 1987, marine biologist Kendra Okafor proposed that deep-sea bioluminescent organisms produce light primarily as a predatory lure, a hypothesis that dominated the field for nearly two decades. However, a 2019 meta-analysis of 342 species across fourteen ocean basins revealed that fewer than 18 percent of bioluminescent organisms use light to attract prey. The majority employ bioluminescence for counter-illumination camouflage, matching the faint downwelling light from the surface to eliminate their silhouettes when viewed from below. Okafor herself acknowledged in a 2021 interview that the predatory-lure model had been "a useful starting point that the data ultimately outgrew," though she noted that the lure function remains critical for certain anglerfish lineages and should not be dismissed entirely.', $lyceon_json$[{"key":"A","text":"Although the predatory-lure hypothesis guided early research on bioluminescence, subsequent data show that most bioluminescent organisms use light for camouflage rather than predation."},{"key":"B","text":"Okafor's 1987 predatory-lure hypothesis has been entirely discredited by recent research demonstrating that no bioluminescent organisms use light to attract prey."},{"key":"C","text":"Counter-illumination camouflage is the only function of bioluminescence that has been conclusively verified through large-scale meta-analysis."},{"key":"D","text":"The 2019 meta-analysis confirmed Okafor's original hypothesis by showing that bioluminescence serves the same function across all fourteen ocean basins studied."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces how the dominant predatory-lure hypothesis was revised by data showing most bioluminescent species use light for camouflage, while acknowledging the lure function still matters for some species. The correct choice accurately captures this nuanced shift. The claim that Okafor''s hypothesis has been entirely discredited overstates the passage, which notes that Okafor herself said the lure function should not be dismissed entirely. The assertion that counter-illumination is the only verified function ignores the passage''s acknowledgment that the lure function remains critical for certain anglerfish lineages. The suggestion that the meta-analysis confirmed Okafor''s original hypothesis directly contradicts the passage''s finding that fewer than 18 percent of species use light as a lure.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PZD6JQ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing an article about the culinary history of fermented foods and wants to emphasize the wide geographic range of fermentation traditions. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RUU1A8', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The Eurasian jay (Garrulus glandarius) caches thousands of acorns each autumn, burying them in scattered locations across its territory. Studies have shown that jays can remember the precise locations of up to 5,000 individual caches and prioritize retrieving those containing perishable items before turning to longer-lasting stores. When a jay notices that another jay has observed it hiding food, it will return later to move the cache to a new, unobserved location — but only if the jay itself has previously stolen from another bird''s cache.', $lyceon_json$[{"key":"A","text":"Jays that have stolen food from others can anticipate that observers may also steal, so they take protective action."},{"key":"B","text":"All Eurasian jays instinctively relocate their caches regardless of whether they have been observed."},{"key":"C","text":"Eurasian jays that cache acorns in autumn do so primarily to prepare food for their offspring rather than for themselves."},{"key":"D","text":"Jays cannot distinguish between individuals that have observed them caching and those that have not."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that jays relocate caches only when observed and only if they have previously stolen from others. The correct inference is that past experience as a thief enables a jay to anticipate theft by observers. The claim that all jays instinctively relocate caches contradicts the passage, which specifies this behavior occurs only when observed and only among jays with theft experience. The suggestion that caching serves primarily to feed offspring introduces a purpose the passage never mentions. The assertion that jays cannot distinguish observers from non-observers contradicts the passage''s statement that jays respond specifically to being watched.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WTMTA8', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although Mendeleev''s 1869 periodic table successfully predicted the existence of several then-undiscovered ______ his arrangement of elements by atomic weight rather than atomic number meant that certain pairs, such as tellurium and iodine, appeared out of sequence—an anomaly not resolved until Henry Moseley''s X-ray spectroscopy experiments in 1913.', $lyceon_json$[{"key":"A","text":"elements: his"},{"key":"B","text":"elements, his"},{"key":"C","text":"elements his"},{"key":"D","text":"elements. His"}]$lyceon_json$::jsonb, 'B', NULL, E'The word ''Although'' at the beginning of the sentence introduces a dependent (subordinate) clause: ''Although Mendeleev''s 1869 periodic table successfully predicted the existence of several then-undiscovered elements.'' When a dependent clause precedes the main clause, a comma is required to separate them. A colon cannot follow a dependent clause, since colons introduce elaboration or lists after independent clauses. Omitting punctuation entirely leaves the reader no signal that the subordinate clause has ended and the main clause has begun. Using a period would incorrectly terminate the dependent clause as though it were a complete sentence, creating a fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YSYKXD', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Historian Tomoko Arai has argued that the 1923 Great Kanto Earthquake did more than destroy physical infrastructure in Tokyo and Yokohama — it fundamentally disrupted the social hierarchies that had governed neighborhood life for generations. Arai documents how post-quake reconstruction committees, which were formed hastily from surviving residents regardless of hereditary status, became permanent fixtures of local governance. __________ the catastrophe, paradoxically, created conditions under which previously excluded groups gained a political foothold that peacetime reforms had failed to provide.', $lyceon_json$[{"key":"A","text":"As a result,"},{"key":"B","text":"On the other hand,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"That is,"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence before the blank describes how hastily formed reconstruction committees became permanent governance bodies, and the sentence after the blank restates this observation at a higher level of abstraction: the catastrophe created conditions for previously excluded groups to gain political power. The final sentence is a reformulation and distillation of the preceding evidence, so "That is," correctly signals a clarifying restatement. "As a result," might seem plausible because the passage involves cause and effect, but the final sentence is not introducing a new consequence — it is rephrasing the same point already made about the committees becoming permanent. "On the other hand," falsely introduces a contrasting perspective when no opposition exists. "Specifically," implies the final sentence narrows to a concrete detail, but it actually broadens to a general conclusion about political inclusion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
